<script lang="ts">
import {onMount,onDestroy} from 'svelte';
import {beforeNavigate} from '$app/navigation';
import {api} from '../../../lib/api';
import type {MembershipStatus} from '../../../lib/membership';
type Member={id:number;name:string;email:string;telephone:string;status:MembershipStatus;card_code?:string;borrower_id?:number|null;submitted_at:string;reviewed_at?:string};
type Action='approve'|'reject'|'suspend'|'reactivate'|'replace-card';
let members:Member[]=[];let filter='pending';let loading=true;let busy=false;let error='';let message='';let lookupCode='';let found:Member|null=null;let lookupError='';let registrationURL='';let configError='';let qrError=false;let disposed=false;let sequence=0;
let confirmation:{member:Member;action:Action}|null=null;
const labels:Record<Action,string>={approve:'Approve membership',reject:'Reject request',suspend:'Suspend membership',reactivate:'Reactivate membership','replace-card':'Replace card'};
beforeNavigate(navigation=>{if(navigation.from&&busy)navigation.cancel();});
onMount(()=>{void load();void config();});onDestroy(()=>{disposed=true;sequence++;});
async function load(){const request=++sequence;loading=true;error='';try{const value=await api<{members:Member[]}>(`/api/members?status=${filter}`);if(!disposed&&request===sequence)members=value.members;}catch(e){if(!disposed&&request===sequence)error=(e as Error).message;}finally{if(!disposed&&request===sequence)loading=false;}}
async function config(){configError='';try{const value=await api<{registration_url:string}>('/api/members/config');const url=new URL(value.registration_url);if(!['https:','http:'].includes(url.protocol)||url.username||url.password)throw new Error('The registration address is not valid.');if(!disposed)registrationURL=url.href;}catch(e){if(!disposed)configError=(e as Error).message;}}
async function review(member:Member,action:Action){if(busy)return;busy=true;error='';message='';try{const value=await api<{member:Member}>(`/api/members/${member.id}/review`,{action});if(disposed)return;if(found?.id===value.member.id)found=value.member;confirmation=null;message=`${member.name}: ${action==='replace-card'?'card replaced':value.member.status}.`;await load();}catch(e){if(!disposed)error=(e as Error).message;}finally{if(!disposed)busy=false;}}
async function lookup(event:SubmitEvent){event.preventDefault();if(busy||!lookupCode.trim())return;busy=true;lookupError='';found=null;try{const value=await api<{member:Member}>('/api/members/lookup',{card_code:lookupCode.trim()});if(!disposed){found=value.member;lookupCode='';}}catch(e){if(!disposed)lookupError=(e as Error).message;}finally{if(!disposed)busy=false;}}
</script>
<svelte:head><title>Library members · Staff library</title></svelte:head>
<h1>Library members</h1><p>Review requests, check member cards and manage active memberships. Approving a request creates a borrowing record; contact details are not independently verified.</p>
<section class="member-registration"><div><h2>Invite people to join</h2>{#if registrationURL}<p>Ask people to connect to the library’s Wi-Fi and scan this code.</p><a class="registration-url" href={registrationURL}>{registrationURL}</a>{#if qrError}<p role="status">The registration QR code is unavailable. Share the link instead.</p>{/if}{:else if configError}<p role="alert">{configError}</p><button class="library-button secondary" onclick={config}>Retry registration link</button>{:else}<p>Loading the registration link…</p>{/if}</div>{#if registrationURL&&!qrError}<img src="/api/members/registration-qr" alt="QR code for the library membership registration page" width="200" height="200" onerror={()=>qrError=true}/>{/if}</section>
<section class="member-lookup"><h2>Scan a member card</h2><form onsubmit={lookup}><label class="library-field">Card code<input bind:value={lookupCode} autocomplete="off" placeholder="Scan the card QR code or type its code" disabled={busy}/></label><button class="library-button" disabled={busy||!lookupCode.trim()}>Find member</button></form>{#if lookupError}<p role="alert" class="library-error">{lookupError}</p>{/if}{#if found}<div class="lookup-result" role="status"><h3>{found.name}</h3><p>Status: <strong>{found.status}</strong></p>{#if found.borrower_id}<p>Borrower record {found.borrower_id}</p><a class="library-button secondary" href={`/staff/loans/?borrower_id=${found.borrower_id}`}>View this member’s loans</a>{/if}<p class="library-help">Only approved members can use their cards. Use the staff library to check out a book.</p><a href="/staff/">Open staff library</a></div>{/if}</section>
<section class="member-queue"><div class="queue-heading"><h2>Membership requests and cards</h2><button class="library-button secondary" disabled={busy||loading} onclick={load}>Refresh list</button></div><label class="library-field filter">Show<select bind:value={filter} disabled={busy} onchange={()=>{confirmation=null;void load();}}><option value="pending">Waiting for approval</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="suspended">Suspended</option><option value="all">All members</option></select></label>{#if error}<p role="alert" class="library-error">{error}</p>{/if}{#if message}<p role="status">{message}</p>{/if}{#if loading}<p role="status">Loading members…</p>{:else if !members.length}<p>No members match this status.</p>{:else}<ul class="members">{#each members as member (member.id)}<li><article><h3>{member.name}</h3><p class="status">{member.status}</p><dl><dt>Email</dt><dd>{member.email}</dd>{#if member.telephone}<dt>Telephone</dt><dd>{member.telephone}</dd>{/if}<dt>Submitted</dt><dd>{new Date(member.submitted_at).toLocaleString('en-GB')}</dd>{#if member.reviewed_at}<dt>Reviewed</dt><dd>{new Date(member.reviewed_at).toLocaleString('en-GB')}</dd>{/if}{#if member.card_code}<dt>Card code</dt><dd class="code">{member.card_code}</dd>{/if}{#if member.borrower_id}<dt>Borrower record</dt><dd><a href={`/staff/loans/?borrower_id=${member.borrower_id}`}>{member.borrower_id} · View loans</a></dd>{/if}</dl><div class="library-actions">{#if member.status==='pending'}<button class="library-button" disabled={busy} onclick={()=>review(member,'approve')}>Approve membership</button><button class="library-button secondary" disabled={busy} onclick={()=>confirmation={member,action:'reject'}}>Reject request</button>{:else if member.status==='approved'}<button class="library-button secondary" disabled={busy} onclick={()=>confirmation={member,action:'suspend'}}>Suspend membership</button><button class="library-button secondary" disabled={busy} onclick={()=>confirmation={member,action:'replace-card'}}>Replace card</button>{:else if member.status==='suspended'}<button class="library-button" disabled={busy} onclick={()=>review(member,'reactivate')}>Reactivate membership</button>{/if}</div>{#if confirmation?.member.id===member.id}<div class="confirmation"><h4>{labels[confirmation.action]} for {member.name}?</h4><p>{confirmation.action==='replace-card'?'The previous card code will stop working. The member must refresh their card in the browser used to register.':confirmation.action==='suspend'?'The member’s card will stop working until you reactivate their membership. Their borrowing history is retained.':'The member will see that their request was not approved when they next refresh their status.'}</p><div class="library-actions"><button class="library-button" disabled={busy} onclick={()=>confirmation&&review(confirmation.member,confirmation.action)}>{busy?'Saving…':labels[confirmation.action]}</button><button class="library-button secondary" disabled={busy} onclick={()=>confirmation=null}>Cancel</button></div></div>{/if}</article></li>{/each}</ul>{/if}</section>
<style>section{margin-block:2rem}h1{font-family:Georgia,serif;font-size:clamp(2rem,6vw,3rem)}h2{font-size:1.5rem;margin-bottom:1rem}.member-registration{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1.5rem;padding:1.5rem;border:1px solid var(--app-line);max-width:54rem}.member-registration img{max-width:100%;height:auto;background:white}.registration-url{display:inline-block;overflow-wrap:anywhere;margin-top:1rem}.member-lookup form{display:flex;align-items:end;gap:1rem;max-width:46rem}.member-lookup label{flex:1;min-width:0}.lookup-result{margin-top:1rem;padding:1rem;background:var(--app-soft);display:grid;gap:.75rem}.queue-heading{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}.filter{max-width:20rem;margin-block:1rem}.members{list-style:none;padding:0;display:grid;gap:1.5rem}.members article{padding:1.5rem;border:1px solid var(--app-line);border-radius:.3rem}.members h3{font-size:1.3rem}.members .status{margin-block:.5rem;text-transform:capitalize}.members dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:.6rem 1.2rem;margin-block:1rem}.members dt{color:var(--app-muted)}.members dd{margin:0;overflow-wrap:anywhere}.code{font-family:monospace}.confirmation{margin-top:1rem;padding:1rem;background:var(--app-soft);display:grid;gap:1rem}.confirmation h4{font-size:1.1rem}@media(max-width:550px){.member-lookup form{flex-wrap:wrap}.member-lookup label{flex-basis:100%}.members article{padding:1rem}.members dl{grid-template-columns:1fr;gap:.3rem}.members dd{margin-bottom:.7rem}}</style>
